ruleSearch.bookList:
.bookList li
<js>
result.toArray().map(o=>{
    var detail = String(o.select('a:eq(0)').attr('href')).replace(/^\//, 'http://www.tadu.com/');
    java.log(detail)
    return {
       name: String(o.select('.bookNm').text()).replace(/\（.*\）/,''),
       author:o.select('.authorNm').text(),
       tags:  String(o.select('span:eq(2)').text()).replace(' • ',','),
       num: String(o.select('span:eq(6)').text()).replace(/\s+/g,''),

       intro: String(o.select('.bookIntro').text()).trim(),     
       cover:o.select('img').attr('data-src').includes('webPic')?'http://suo.im/6mlA9F':o.select('img').attr('data-src'),
       catalogUrl:o.select('.look_readBtn').attr('href')
    }
});
</js>

exploreUrl:
@js:let boyTypes = [
    {i: 0, n: "  全部分类  "},
    {i: 99, n: "📔东方玄幻"},
    {i: 103, n: "📕现代都市"},
    {i: 135, n: "📗脑洞创意"},
    {i: 108, n: "📘历史架空"},
    {i: 113, n: "📙军事战争"},
    {i: 112, n: "📒游戏竞技"},
    {i: 109, n: "📔武侠仙侠"},
    {i: 111, n: "📕科幻末世"},
    {i: 128, n: "📗灵异悬疑"},
    {i: 107, n: "📘西方奇幻"},
    {i: 281, n: "📙短篇小说"}
];

let girlTypes = [
    {i: 129, n: "📔古代言情"},
    {i: 133, n: "📕幻想言情"},
    {i: 104, n: "📗现代言情"},
    {i: 105, n: "📘浪漫青春"},
    {i: 288, n: "📙悬疑小说"},
    {i: 291, n: "📒短篇小说"},
];

let sort = [
    {i: 0, n: "全部字数"},
    {i: 11, n: "100万字以下"},
    {i: 12, n: "200万字以下"},
];

let girlRank = [
    {i: 'hour72', n: "🔥人气榜"},
    {i: 'potential', n: "🆕新书榜"},
    {i: 'votes', n: "💰银票榜"},
    {i: 'wholebook', n: "📚完本榜"},
];

let boyRank = [
    {i: 'hour72', n: "🔥人气榜"},
    {i: 'potential', n: "🆕新书榜"},
    {i: 'votes', n: "💰银票榜"},
    {i: 'interactive', n: "🤼‍互动榜"},
    {i: 'wholebook', n: "📚完本榜"},
];

let titleStyle = {
    layout_flexGrow: 0,
    layout_flexShrink: 1,
    layout_alignSelf: "auto",
    layout_flexBasisPercent: 1,
    layout_wrapBefore: false
};
const defaultStyle = {
    layout_flexBasisPercent: .28
};
let result = [];
for (let rank of boyRank) {
    for (let s of sort) {
        let title = `🔹 男频·${rank.n}·${s.n} 🔹`;
        result.push({
            title: title,
            url: "",
            style: titleStyle
        });
        for (let type of boyTypes) {
            result.push({
                title: type.n,
                url: `/book/rank/list/0-${rank.i}-${type.i}-${s.i}-{{page}}`,
                style: defaultStyle
            });
        }
    }
}
for (let rank of girlRank) {
    for (let s of sort) {
        let title = `🔸 ♀️女频·${rank.n}·${s.n}·可点击 🔸`;
        result.push({
            title: title,
            url: `/book/rank/list/3-${rank.i}-0-${s.i}-{{page}}`,
            style: titleStyle
        });
        for (let type of girlTypes) {
            result.push({
                title: type.n,
                url: `/book/rank/list/3-${rank.i}-${type.i}-${s.i}-{{page}}`,
                style: defaultStyle
            });
        }
    }
}
JSON.stringify(result);

